#!/usr/bin/env python3
"""Test production library rows in an isolated 300-book simulator fixture."""
from pathlib import Path
import argparse
import subprocess
import tempfile
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--device', required=True)
args = parser.parse_args()
r = Path(tempfile.mkdtemp(prefix='NoveliaLibraryUIRegression-'))
root = Path(__file__).resolve().parents[1]
s = (root / 'iOSApp/Features/Library/LibraryViews.swift').read_text()
components = s[s.index('struct LibraryBookRow:'):s.index('// MARK: - 搜索与排序控件')]
style = s[s.index('private extension View {'):s.index('// MARK: - 打开阅读')]
fixture = '\nimport SwiftUI\nimport UIKit\nprivate enum NoveliaStyle { static let paper = Color(uiColor: .systemGroupedBackground); static let card = Color(uiColor: .secondarySystemGroupedBackground); static let ink = Color.primary; static let muted = Color.secondary; static let brandGreen = Color.green }\nenum Format { case epub; var title: String { "EPUB" } }\nstruct Record { let id: String }\nstruct LibraryBook: Identifiable {\n enum Origin { case webNovel(Record), wenku(Record) }\n var isWenku: Bool { Int(key)! % 2 == 0 }; let key: String; var id: String { key }; var title: String { "Synthetic " + key }; let author = "Test Author"\n let format = Format.epub; var categoryTitle: String { "文库" }; let fileURL: URL; let coverURL: URL?\n var origin: Origin { .wenku(Record(id: key)) }\n}\nstruct LibraryReadingStatus { var detail = "未读"; var fraction: Double?; var lastReadAt: Date?; var isUnread: Bool { lastReadAt == nil } }\n@MainActor final class LibraryStateStore: ObservableObject {\n static let shared = LibraryStateStore(); @Published var series = LibrarySeriesState(); @Published var tick = 0\n func status(for book: LibraryBook) -> LibraryReadingStatus { .init(detail: "进度 \\(tick)") }\n func seriesName(for book: LibraryBook) -> String? { series.seriesID(forBook: book.key).flatMap { series.series[$0]?.name } }\n func assign(_ book: LibraryBook, to id: String?) { series.assign(book: book.key, to: id) }\n}\nfinal class WebNovelDownloadStore: ObservableObject { }\nfinal class WenkuLocalLibraryStore: ObservableObject { }\nfinal class LibraryBookActions { var newSeriesName = ""; var newSeriesBook: LibraryBook?; var pendingDelete: LibraryBook?; var actionError: String? }\nenum LibraryMover {\n static func moveToWenku(_ record: Record, web: WebNovelDownloadStore, wenku: WenkuLocalLibraryStore, state: LibraryStateStore) async throws {}\n static func moveToNetwork(_ record: Record, web: WebNovelDownloadStore, wenku: WenkuLocalLibraryStore, state: LibraryStateStore) throws {}\n}\n@main struct TapRegressionApp: App { var body: some Scene { WindowGroup { TestScreen() } } }\nstruct TestScreen: View {\n @StateObject var web = WebNovelDownloadStore(); @StateObject var wenku = WenkuLocalLibraryStore()\n @ObservedObject var state = LibraryStateStore.shared\n @State var sourceFilter = LibrarySourceFilter.all; @State var query = ""; @State var reverse = false; @State var opened = ""\n let actions = LibraryBookActions()\n let books: [LibraryBook] = (0..<300).map { LibraryBook(key: String(format: "%03d", $0), fileURL: URL(fileURLWithPath: "/tmp/test.epub"), coverURL: nil) }\n var visible: [LibraryBook] { let filtered = books.filter { sourceFilter.includes(isWenku: $0.isWenku) && (query.isEmpty || $0.title.contains(query)) }; return reverse ? filtered.reversed() : filtered }\n var body: some View {\n  NavigationStack {\n   List {\n    HStack { sourceFilterMenu; Text("全部书籍 \\(visible.count)") }.libraryListRow()\n    ForEach(visible) { book in\n     LibraryBookRow(book: book, actions: actions) { opened = $0.key }.libraryListRow()\n    }\n   }.libraryListStyle().navigationTitle("书库")\n    .searchable(text: $query)\n    .toolbar { Button("倒序") { reverse.toggle() }; Button("更新进度") { state.tick += 1 } }\n    .safeAreaInset(edge: .bottom) { Text("Opened: \\(opened)") }\n  }.environmentObject(web).environmentObject(wenku).environmentObject(state)\n }\n}\n'
menu = (root / 'iOSApp/Features/Library/LibraryViews.swift').read_text()
menu = menu[menu.index('    private var sourceFilterMenu:'):menu.index('    @ViewBuilder\n    private var searchBar:')]
fixture += '\nextension TestScreen {\n' + menu + '}\n'
fixture += (root / 'Sources/NoveliaIOSCore/Features/Library/LibraryOrganizer.swift').read_text() + components + style + (root / 'iOSApp/Shared/CoverImage.swift').read_text()
(r / 'TapRegression.swift').write_text(fixture)
(r / 'TapTests.swift').write_text('\nimport XCTest\nfinal class TapTests: XCTestCase {\n func testStableRowsAfterScrollingSortingAndProgressUpdates() {\n  let app = XCUIApplication(); app.launch()\n  XCTAssertTrue(app.buttons["library-book-000"].waitForExistence(timeout: 5))\n  for _ in 0..<4 {\n   app.swipeUp(); app.buttons["更新进度"].tap()\n   let rows = app.buttons.matching(NSPredicate(format: "identifier BEGINSWITH \'library-book-\' ")).allElementsBoundByIndex.filter { $0.isHittable }\n   let ids = rows.map { $0.identifier }\n   XCTAssertFalse(ids.isEmpty); XCTAssertEqual(ids.count, Set(ids).count)\n  }\n  app.buttons["倒序"].tap()\n  for _ in 0..<6 { app.swipeDown() }\n  let first = app.buttons["library-book-299"]\n  XCTAssertTrue(first.waitForExistence(timeout: 5)); XCTAssertTrue(first.isHittable)\n  first.tap()\n  XCTAssertTrue(app.staticTexts["Opened: 299"].exists)\n }\n func testSearchHasExactlyOneMatchingBook() {\n  let app = XCUIApplication(); app.launch(); app.swipeDown()\n  let search = app.searchFields.firstMatch\n  XCTAssertTrue(search.waitForExistence(timeout: 5)); search.tap(); search.typeText("Synthetic 042")\n  XCTAssertTrue(app.buttons["library-book-042"].waitForExistence(timeout: 5))\n  XCTAssertEqual(app.buttons.matching(identifier: "library-book-042").count, 1)\n }\n func testSourceSelection() {\n  let app = XCUIApplication(); app.launch()\n  app.buttons["书籍来源：全部"].tap(); app.buttons["网络小说"].tap()\n  XCTAssertTrue(app.buttons["library-book-001"].waitForExistence(timeout: 5))\n  XCTAssertFalse(app.buttons["library-book-000"].exists)\n  app.buttons["书籍来源：网络小说"].tap(); app.buttons["文库"].tap()\n  XCTAssertTrue(app.buttons["library-book-000"].waitForExistence(timeout: 5))\n  XCTAssertFalse(app.buttons["library-book-001"].exists)\n }\n func testScrollingPerformance() {\n  let app = XCUIApplication(); app.launch()\n  let options = XCTMeasureOptions(); options.iterationCount = 3\n  measure(metrics: [XCTOSSignpostMetric.scrollDecelerationMetric], options: options) { app.swipeUp() }\n }\n}\n')
